class SmartProxy:  # Subject와 같은 인터페이스
    def __init__(self, factory):
        self.factory = factory
        self.real = None
        self.ref_count = 0
        self.lock = Lock()

    def acquire(self):
        self.ref_count += 1  # 참조 카운트 증가

    def release(self):
        self.ref_count -= 1
        if self.ref_count == 0:
            self.real = None  # 마지막 참조 해제 시 소멸

    def request(self, *args):
        with self.lock:  # 동시 접근 제어(락)
            if self.real is None:
                self.real = self.factory()  # 최초 접근 시 생성
            log('request', args)  # 접근 로깅 후 위임
            return self.real.request(*args)
